css:
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
html{scroll-behavior:smooth;}
body{font-family:'DM Sans',sans-serif;background:#F8F7F3;color:#0D0D0D;line-height:1.6;}
a{color:inherit;text-decoration:none;}
img{display:block;}
nav{position:fixed;top:0;left:0;right:0;z-index:200;transition:background 200ms,border-color 200ms;border-bottom:1px solid transparent;}
nav.scrolled{background:#F8F7F3;border-bottom-color:#E5E1D9;}
.nav-inner{max-width:1440px;margin:0 auto;padding:0 56px;height:72px;display:flex;align-items:center;justify-content:space-between;}
.nav-logo{height:28px;object-fit:contain;filter:invert(1) brightness(100);transition:filter 200ms;}
nav.scrolled .nav-logo{filter:none;}
.nav-links{display:flex;align-items:center;gap:26px;}
.nav-links > a,.nav-drop-t{font-size:14px;font-weight:500;color:rgba(255,255,255,0.65);transition:color 150ms;letter-spacing:0.01em;}
.nav-links > a:hover,.nav-drop-t:hover{color:white;}
nav.scrolled .nav-links > a,nav.scrolled .nav-drop-t{color:#3A3A3A;}
nav.scrolled .nav-links > a:hover,nav.scrolled .nav-drop-t:hover{color:#1C3B2D;}
.nav-apply{background:rgba(255,255,255,0.12);color:white;padding:8px 18px;border-radius:6px;font-size:13px;font-weight:600;border:1.5px solid rgba(255,255,255,0.3);transition:all 200ms;letter-spacing:0.01em;}
.nav-apply:hover{background:rgba(255,255,255,0.2);border-color:rgba(255,255,255,0.5);}
nav.scrolled .nav-apply{background:#1C3B2D;border-color:#1C3B2D;color:white;}
nav.scrolled .nav-apply:hover{background:#2A5C46;}
/* dropdown */
.nav-drop{position:relative;}
.nav-drop-t{background:none;border:none;cursor:pointer;font-family:inherit;display:inline-flex;align-items:center;gap:5px;padding:0;}
.nav-drop-menu{position:absolute;top:calc(100% + 10px);left:-16px;min-width:210px;background:#FFFFFF;border:1px solid #E5E1D9;border-radius:9px;padding:8px;box-shadow:0 12px 34px rgba(13,13,13,0.14);display:none;}
.nav-drop-menu::before{content:"";position:absolute;top:-12px;left:0;right:0;height:12px;}
.nav-drop:hover .nav-drop-menu,.nav-drop:focus-within .nav-drop-menu,.nav-drop.open .nav-drop-menu{display:block;}
.nav-drop-menu a{display:block;padding:9px 12px;border-radius:6px;font-size:14px;font-weight:500;color:#3A3A3A;transition:background 130ms,color 130ms;}
.nav-drop-menu a:hover{background:#F0EDE6;color:#1C3B2D;}
.wrap{max-width:1440px;margin:0 auto;padding:100px 80px;}
.wrap-sm{max-width:1440px;margin:0 auto;padding:80px 80px;}
.over{font-size:12px;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;color:#727272;margin-bottom:12px;}
.over-w{color:rgba(255,255,255,0.45);}
.h2{font-family:'Barlow',sans-serif;font-size:52px;font-weight:700;line-height:1.08;letter-spacing:-0.01em;color:#0D0D0D;margin-bottom:20px;}
.h2-w{color:white;}
.h3{font-family:'Barlow',sans-serif;font-size:24px;font-weight:700;color:#0D0D0D;line-height:1.2;margin-bottom:8px;}
.body{font-size:18px;line-height:1.65;color:#3A3A3A;}
.sm{font-size:15px;line-height:1.55;color:#727272;}
.xs{font-size:12px;color:#B0ADA6;}
.mono{font-family:'DM Mono',monospace;}
.card{background:#fff;border:1px solid #E5E1D9;border-radius:10px;padding:28px 32px;}
.card-t{border-top:3px solid #1C3B2D;}
.btn-f{display:inline-flex;align-items:center;gap:8px;background:#1C3B2D;color:white;padding:14px 28px;border-radius:6px;font-size:15px;font-weight:600;transition:background 150ms;cursor:pointer;border:none;}
.btn-f:hover{background:#2A5C46;}
.btn-ol{display:inline-flex;align-items:center;gap:8px;background:transparent;color:rgba(255,255,255,0.75);padding:14px 28px;border-radius:6px;font-size:15px;font-weight:500;border:1.5px solid rgba(255,255,255,0.3);transition:all 150ms;cursor:pointer;}
.btn-ol:hover{border-color:rgba(255,255,255,0.7);color:white;}
.btn-w{background:#fff;color:#1C3B2D;}
.btn-w:hover{background:#E5E1D9;}
.g2{display:grid;grid-template-columns:repeat(2,1fr);gap:24px;}
.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;}
.g4{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;}
.tag{display:inline-flex;align-items:center;padding:3px 9px;border-radius:4px;font-size:11px;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;background:#F0EDE6;color:#727272;}
.tag-f{background:#BDDDD3;color:#1C3B2D;}
.tag-br{background:#F2E8D5;color:#6B4E2A;}
@keyframes tick{0%{transform:translateX(0);}100%{transform:translateX(-50%);}}
.ticker{overflow:hidden;background:#0D0D0D;height:44px;display:flex;align-items:center;}
.ticker-inner{display:flex;white-space:nowrap;animation:tick 34s linear infinite;}
.ti{font-family:'DM Mono',monospace;font-size:11px;letter-spacing:0.06em;padding:0 20px;color:rgba(255,255,255,0.25);}
.ti-b{font-weight:600;letter-spacing:0.12em;color:rgba(255,255,255,0.65);}
/* hero */
#top{background:#1C3B2D;min-height:88vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:150px 80px 90px;position:relative;overflow:hidden;}
.hero-mark{font-family:'Barlow Condensed',sans-serif;font-size:15px;font-weight:800;letter-spacing:0.30em;color:rgba(255,255,255,0.5);margin-bottom:22px;text-transform:uppercase;}
.hero-h1{font-family:'Barlow Condensed',sans-serif;font-size:84px;font-weight:900;color:white;letter-spacing:0.03em;line-height:0.95;text-transform:uppercase;max-width:1000px;margin-bottom:26px;}
.hero-lede{font-size:19px;line-height:1.6;color:rgba(255,255,255,0.72);max-width:640px;margin:0 auto 40px;}
.chips{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-bottom:40px;}
.chip{border:1px solid rgba(255,255,255,0.18);border-radius:8px;padding:12px 20px;min-width:150px;}
.chip-l{font-family:'DM Mono',monospace;font-size:10px;letter-spacing:0.12em;text-transform:uppercase;color:rgba(255,255,255,0.4);margin-bottom:3px;}
.chip-v{font-size:15px;font-weight:600;color:white;}
.hero-ctas{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;}
/* protocol */
.proto{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;}
.proto-c{background:#fff;border:1px solid #E5E1D9;border-radius:10px;padding:26px 28px;display:flex;gap:18px;}
.proto-i{width:38px;height:38px;flex:0 0 38px;border-radius:8px;background:#1C3B2D;color:#fff;display:flex;align-items:center;justify-content:center;font-family:'Barlow',sans-serif;font-weight:800;font-size:15px;}
/* numbered */
.num{display:grid;grid-template-columns:64px 1fr;border-top:1px solid #E5E1D9;padding:26px 0;gap:8px;}
.num-n{font-family:'DM Mono',monospace;font-size:12px;color:#B0ADA6;letter-spacing:0.10em;padding-top:5px;}
/* timeline */
.tl{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;}
.tl-c{background:#fff;border:1px solid #E5E1D9;border-top:3px solid #B8924A;border-radius:10px;padding:26px 28px;}
.tl-p{font-family:'DM Mono',monospace;font-size:11px;letter-spacing:0.10em;text-transform:uppercase;color:#B8924A;margin-bottom:10px;}
/* note */
.note{background:#F0EDE6;border:1px solid #E5E1D9;border-left:3px solid #B8924A;border-radius:10px;padding:30px 34px;}
/* cta */
.cta{background:#0D0D0D;text-align:center;}
.cta-h{font-family:'Barlow Condensed',sans-serif;font-size:80px;font-weight:900;color:white;letter-spacing:0.03em;line-height:0.95;text-transform:uppercase;margin-bottom:22px;}
/* footer */
.site-footer{background:#0D0D0D;border-top:1px solid rgba(255,255,255,0.06);padding:32px 80px;}
.footer-inner{max-width:1440px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap;}
.fcap{color:rgba(255,255,255,0.2);letter-spacing:0.08em;text-transform:uppercase;}
.flinks{display:flex;gap:22px;flex-wrap:wrap;}
.flinks a{font-family:'DM Mono',monospace;font-size:12px;color:rgba(255,255,255,0.25);letter-spacing:0.06em;text-transform:uppercase;transition:color 150ms;}
.flinks a:hover{color:rgba(255,255,255,0.75);}
@media (max-width:1100px){
  .nav-inner{padding:0 32px;}
  .nav-links{gap:18px;}
  .wrap,.wrap-sm{padding:80px 40px;}
  .h2{font-size:40px;}
  .proto,.g3,.tl{grid-template-columns:1fr;}
  .hero-h1{font-size:62px;}
  .cta-h{font-size:58px;}
}
@media (max-width:680px){
  .nav-inner{padding:0 18px;height:60px;}
  .nav-links{display:none;}
  .nav-logo{height:24px;}
  .nav-apply{padding:7px 14px;font-size:12px;}
  .wrap,.wrap-sm{padding:56px 20px;}
  .h2{font-size:32px;}
  .h3{font-size:21px;}
  .body{font-size:16px;}
  #top{min-height:auto;padding:104px 20px 64px;}
  .hero-h1{font-size:44px;}
  .cta-h{font-size:42px;}
  .chip{min-width:0;flex:1 1 140px;}
  .hero-ctas a{width:100%;justify-content:center;}
  .footer-inner{flex-direction:column;text-align:center;}
  .flinks{justify-content:center;}
  html,body{overflow-x:hidden;}
}
